"""Every fixture under runner/ is generated by tests/make_synthetic_fixtures.py: none is hand-made or captured."""
import os, subprocess, sys, tempfile, unittest
from helpers import RUNNER_DIR, HERE
import make_synthetic_fixtures as G

FIXTURE_DIRS = ("fixtures", os.path.join("tests", "fixtures"))
DOCS = {os.path.join("fixtures", "FIXTURES.md")}


def on_disk():
    out = set()
    for sub in FIXTURE_DIRS:
        for dp, dn, fn in os.walk(os.path.join(RUNNER_DIR, sub)):
            dn[:] = [d for d in dn if d != "__pycache__"]
            out.update(os.path.relpath(os.path.join(dp, n), RUNNER_DIR) for n in fn)
    return out - DOCS


class GeneratedFixtureTests(unittest.TestCase):
    def test_files_on_disk_match_the_generator(self):
        files = G.build_files()
        for rel, text in sorted(files.items()):
            with self.subTest(fixture=rel):
                with open(os.path.join(RUNNER_DIR, rel), "rb") as f:
                    self.assertEqual(f.read(), text.encode("utf-8"), "stale: run python3 runner/tests/make_synthetic_fixtures.py")

    def test_no_fixture_outside_the_generator(self):
        self.assertEqual(sorted(on_disk() - set(G.build_files())), [])

    def test_generator_is_deterministic_and_relative(self):
        a, b = G.build_files(), G.build_files()
        self.assertEqual(a, b)
        for rel in a:
            self.assertFalse(os.path.isabs(rel) or ".." in rel.split(os.sep), rel)
            self.assertTrue(rel.startswith(FIXTURE_DIRS), rel)

    def test_check_and_write_cli(self):
        gen = os.path.join(HERE, "make_synthetic_fixtures.py")
        with tempfile.TemporaryDirectory() as d:
            r = subprocess.run([sys.executable, "-B", gen, "--check", "--out", d], capture_output=True, text=True, timeout=60)
            self.assertEqual(r.returncode, 1, r.stdout + r.stderr)  # empty dir: every fixture missing
            r = subprocess.run([sys.executable, "-B", gen, "--out", d], capture_output=True, text=True, timeout=60)
            self.assertEqual(r.returncode, 0, r.stderr)
            r = subprocess.run([sys.executable, "-B", gen, "--check", "--out", d], capture_output=True, text=True, timeout=60)
            self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
            p = os.path.join(d, "tests", "fixtures", "backlog_queue.yaml")
            with open(p, "a") as f:
                f.write("# drift\n")
            r = subprocess.run([sys.executable, "-B", gen, "--check", "--out", d], capture_output=True, text=True, timeout=60)
            self.assertEqual(r.returncode, 1)
            self.assertIn("backlog_queue.yaml", r.stdout)

    def test_ansi_screen_is_never_written(self):
        # ESC and CR are control characters: the ANSI/CRLF screen exists in memory only (test_usage imports it).
        self.assertIn("\x1b[", G.ANSI)
        self.assertIn("\r\n", G.ANSI)
        self.assertFalse(any("\x1b" in t or "\r" in t for t in G.build_files().values()))

    def test_projects_fixture_counts(self):
        # 9 assistant lines with usage = 7 messages + 1 duplicate + 1 <synthetic> (test_usage.LocalTests)
        lines = [l for rel, t in G.build_files().items() if "/projects/" in rel for l in t.splitlines()]
        assistant = [l for l in lines if '"type":"assistant"' in l and '"usage"' in l]
        self.assertEqual(len(assistant), 9)
        self.assertEqual(sum('"<synthetic>"' in l for l in assistant), 1)


if __name__ == "__main__":
    unittest.main()
